import time

N = 256

# EVOLVE-BLOCK-START
def construct():
    start_time = time.time()
    deadline = start_time + 25.0  # Safety margin before 30s limit
    
    # We will use a greedy approach:
    # 1. Maintain a set of selected numbers S.
    # 2. Maintain a set of sums K generated by S.
    # 3. Maintain a set of 'alive' candidates that can currently be added to S.
    # 4. In each step, for each alive candidate x, count how many other alive candidates
    #    would be killed if x were selected.
    # 5. Select the x that kills the most.
    # 6. Update S, K, and alive set.
    
    # Initial state
    selected = []
    sums = set()
    
    # All numbers 1..N are initially alive
    alive = set(range(1, N + 1))
    
    def can_add(x, current_sums, current_selected):
        # Check if x can be added to current_selected without breaking Sidon property
        # New sums: 2*x and x+s for s in current_selected
        # If any new sum is in current_sums, or if new sums collide with each other, it fails.
        # Note: x is not in current_selected.
        
        new_sums = [2 * x]
        for s in current_selected:
            new_sums.append(x + s)
        
        # Check collisions with existing sums
        for ns in new_sums:
            if ns in current_sums:
                return False
        
        # Check collisions among new sums
        # Since x is fixed and s are distinct, x+s are distinct.
        # 2*x can collide with x+s if 2x = x+s => x=s. But x not in selected.
        # So 2*x is distinct from x+s.
        # Thus, no internal collisions among new sums.
        
        return True

    def get_killed(x, current_sums, current_selected, alive_candidates):
        # Returns the set of y in alive_candidates that would be blocked if x is added
        # y is blocked if y cannot be added to (current_selected + [x])
        
        # Hypothetical new sums
        hyp_sums = set(current_sums)
        hyp_sums.add(2 * x)
        for s in current_selected:
            hyp_sums.add(x + s)
            
        killed = set()
        for y in alive_candidates:
            if y == x:
                continue
            # Check if y can be added to the hypothetical set
            # New sums for y: 2*y and y+h for h in (current_selected + [x])
            # We need to check if any of these are in hyp_sums or collide with each other.
            
            # 1. Check 2*y against hyp_sums
            if 2 * y in hyp_sums:
                killed.add(y)
                continue
                
            # 2. Check y+h against hyp_sums for h in current_selected
            # and also h=x
            # If y+h is in hyp_sums, y is blocked.
            
            blocked = False
            # Check against existing selected elements
            for s in current_selected:
                if (y + s) in hyp_sums:
                    blocked = True
                    break
            if blocked:
                killed.add(y)
                continue
                
            # Check against x specifically
            # The sum y+x is in hyp_sums (since we added x to sums).
            # Wait, the condition is: can y be added to S' = S U {x}?
            # The sums of S' are hyp_sums.
            # If we add y to S', we generate new sums: 2*y and y+s' for s' in S'.
            # One of s' is x. So y+x is a new sum.
            # Is y+x in hyp_sums?
            # hyp_sums contains x+s for s in S. It does NOT contain y+x unless y is in S (it's not) or x is in S (it's not, but we are adding it).
            # Actually, hyp_sums is the set of sums generated by S U {x}.
            # So x+s for s in S are in hyp_sums.
            # Does hyp_sums contain y+x? No, because y is not in S.
            # So y+x is a *new* sum generated by adding y.
            # We must ensure this new sum y+x is not already in hyp_sums.
            # If y+x is in hyp_sums, then adding y creates a duplicate sum.
            
            if (y + x) in hyp_sums:
                killed.add(y)
                continue
                
            # Also check if 2*y collides with any y+s' ?
            # 2*y = y+s' => y=s'. y not in S'.
            # So 2*y is distinct from y+s'.
            
            # So y is NOT killed.
        
        return killed

    while alive:
        if time.time() > deadline:
            break
            
        best_x = None
        max_kills = -1
        best_killed_set = set()
        
        # To optimize, we can just iterate through alive
        # N is small, so O(N^2) per step is fine.
        # Number of steps is ~16. Total ops ~ 16 * 256 * 256 = 1M.
        
        for x in alive:
            # x is in alive, so it is compatible with current S.
            killed = get_killed(x, sums, selected, alive)
            kills_count = len(killed)
            
            if kills_count > max_kills:
                max_kills = kills_count
                best_x = x
                best_killed_set = killed
                
        if best_x is None:
            break
            
        # Add best_x to selected
        selected.append(best_x)
        
        # Update sums
        sums.add(2 * best_x)
        for s in selected[:-1]: # exclude best_x itself from this loop to avoid double counting or self-ref?
             # Actually, we need to add best_x + s for all s in PREVIOUS selected.
             # And 2*best_x is already added.
             pass
        
        # Let's do it cleanly:
        # Remove best_x from alive
        alive.remove(best_x)
        
        # Update sums
        sums.add(2 * best_x)
        for s in selected[:-1]:
            sums.add(best_x + s)
            
        # Remove killed elements from alive
        alive -= best_killed_set

    return selected
# EVOLVE-BLOCK-END
